import * as T from './vendor/three.module.js';
// Original training ecology, deliberately separate from real map data.
export function createEcology(scene,profile){
 const sky=new T.Group(),sea=new T.Group();scene.add(sky,sea);sea.visible=false;
 const geometries=[],materials=[],textures=[];const geo=g=>(geometries.push(g),g);const mat=m=>(materials.push(m),m);
 const sphere=geo(new T.SphereGeometry(1,10,7)),stone=mat(new T.MeshLambertMaterial({color:0x7c8276})),sand=mat(new T.MeshLambertMaterial({color:0x8f9a80}));
 const bottom=new T.Mesh(geo(new T.PlaneGeometry(2500,2500)),sand);bottom.rotation.x=-Math.PI/2;bottom.position.y=-22;sea.add(bottom);
 const rockCount=profile.effects?55:22,rocks=new T.InstancedMesh(sphere,stone,rockCount),matrix=new T.Matrix4(),pos=new T.Vector3(),quat=new T.Quaternion(),scale=new T.Vector3();
 for(let i=0;i<rockCount;i++){pos.set(Math.sin(i*13.7)*100,-21,Math.cos(i*9.3)*110);scale.set(1.5+(i%5),2+(i%4),2+(i%3));matrix.compose(pos,quat,scale);rocks.setMatrixAt(i,matrix);}sea.add(rocks);
 const coral=new T.Group(),plants=new T.Group();sea.add(coral,plants);const coralGeo=geo(new T.ConeGeometry(1,3,7)),coralMat=mat(new T.MeshLambertMaterial({color:0xbb9884}));
 const corals=new T.InstancedMesh(coralGeo,coralMat,profile.effects?80:30);for(let i=0;i<corals.count;i++){pos.set(Math.sin(i*3.17)*70,-19.5,Math.cos(i*8.31)*80);scale.set(.3+(i%4)*.3,.6+(i%3)*.6,.5);quat.setFromAxisAngle(new T.Vector3(0,0,1),Math.sin(i)*.25);matrix.compose(pos,quat,scale);corals.setMatrixAt(i,matrix);corals.setColorAt(i,new T.Color().setHSL(.05+(i%6)*.05,.26,.52));}coral.add(corals);
 const leaf=geo(new T.PlaneGeometry(.5,7)),leafMat=mat(new T.MeshLambertMaterial({color:0x568056,side:T.DoubleSide}));for(let i=0;i<18;i++){const p=new T.Mesh(leaf,leafMat);p.position.set(Math.sin(i*8)*35,-18,Math.cos(i*7)*45);p.rotation.z=Math.sin(i)*.2;plants.add(p);}
 const fishCount=profile.effects?30:12,fishMat=mat(new T.MeshLambertMaterial({color:0xd9b277}));
 const bodies=new T.InstancedMesh(sphere,fishMat,fishCount),tails=new T.InstancedMesh(geo(new T.ConeGeometry(.4,.7,3)),fishMat,fishCount);sea.add(bodies,tails);
 const cloudMat=mat(new T.MeshLambertMaterial({color:0xe4edf0,transparent:true,opacity:.76,depthWrite:false})),clouds=new T.InstancedMesh(sphere,cloudMat,profile.effects?38:14);
 for(let i=0;i<clouds.count;i++){pos.set(Math.sin(i*4.9)*300,85+(i%6)*15,Math.cos(i*8.7)*300);scale.set(12+(i%6)*5,5+(i%3)*3,9+(i%5)*3);quat.identity();matrix.compose(pos,quat,scale);clouds.setMatrixAt(i,matrix);}sky.add(clouds);
 const axisY=new T.Vector3(0,1,0),rotation=new T.Euler();
 const birdCount=profile.effects?10:4,birdMat=mat(new T.MeshLambertMaterial({color:0x4f6670,side:T.DoubleSide})),birdGeo=geo(new T.PlaneGeometry(1.4,.23)),birds=new T.InstancedMesh(birdGeo,birdMat,birdCount*2);sky.add(birds);
 let habitat='sea',textureStarted=false,reefTexture=null,disposed=false;
 function setHabitat(next){habitat=next;coral.visible=next==='sea';plants.visible=next==='lake';sand.color.set(next==='lake'?0x677a55:0x8f9a80);fishMat.color.set(next==='lake'?0x9cac8b:0xd9b277);sand.transparent=next==='sea';sand.opacity=next==='sea'?.16:1;sand.depthWrite=next!=='sea';if(next==='sea'&&!textureStarted){textureStarted=true;new T.TextureLoader().load(globalThis.AERO_REEF_ASSET||new URL('assets/reef-training.webp',document.baseURI).href,texture=>{if(disposed){texture.dispose();return}texture.colorSpace=T.SRGBColorSpace;textures.push(texture);reefTexture=texture},undefined,()=>{});}}
 function update(s){const water=s.vehicle==='water';sea.visible=water;sky.visible=!water;if(water){for(let i=0;i<fishCount;i++){const a=s.time*.18+i*.9,x=Math.sin(a)*25+(i%4)*5,z=Math.cos(a)*25-18,y=-3-(i%5)*2;pos.set(x,y,z);quat.setFromAxisAngle(axisY,-a);scale.set(.55,.19,.17);matrix.compose(pos,quat,scale);bodies.setMatrixAt(i,matrix);pos.set(x-Math.cos(a)*.5,y,z-Math.sin(a)*.5);quat.setFromEuler(rotation.set(0,-a,Math.PI/2+Math.sin(s.time*5+i)*.15));scale.set(1,1,1);matrix.compose(pos,quat,scale);tails.setMatrixAt(i,matrix);}bodies.instanceMatrix.needsUpdate=true;tails.instanceMatrix.needsUpdate=true;}
 else{for(let i=0;i<birdCount;i++){const a=s.time*.06+i*6.2,x=Math.sin(a)*65,z=Math.cos(a)*70-40,y=25+i*5;for(let wing=0;wing<2;wing++){pos.set(x+(wing?1:-1)*.55,y,z);quat.setFromEuler(rotation.set(-Math.PI/2,0,(wing?1:-1)*(.18+Math.sin(s.time*3+i)*.38)));scale.set(1,1,1);matrix.compose(pos,quat,scale);birds.setMatrixAt(i*2+wing,matrix)}}birds.instanceMatrix.needsUpdate=true;}}
 return{update,setHabitat,get backdropTexture(){return habitat==='sea'?reefTexture:null},dispose(){disposed=true;sky.traverse(o=>{if(o.isInstancedMesh)o.dispose()});sea.traverse(o=>{if(o.isInstancedMesh)o.dispose()});geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());textures.forEach(t=>t.dispose());scene.remove(sky,sea)}};
}
